if frame not in self._vel_dict:
    # Search each branch up to its first known velocity. Keep searching
    # after finding the nearest source to diagnose ambiguous branches.
    parents = {self: None}
    queue = deque([self])
    candidates = []
    loop = False
    while queue:
        node = queue.popleft()
        for neighbor, neighbor_pos in node._pos_dict.items():
            if neighbor is parents[node]:
                continue
            try:
                neighbor_pos.express(frame)
            except ValueError:
                continue
            if neighbor in parents:
                loop = True
                continue
            parents[neighbor] = node
            if frame in neighbor._vel_dict:
                candidates.append(neighbor)
            else:
                queue.append(neighbor)
    if loop:
        warn('Loops are defined among the positions of points. '
             'This is likely not desired and may cause errors '
             'in your calculations.', UserWarning, stacklevel=2)
    if not candidates:
        raise ValueError('Velocity of point ' + self.name + ' has not been'
                         ' defined in ReferenceFrame ' + frame.name)
    if len(candidates) > 1:
        warn('Multiple points have their velocity defined in '
             'ReferenceFrame %s: %s. The velocity of point %s will be '
             'calculated using point %s, but it may be inconsistent '
             'with velocities calculated using the other points. '
             'Check that the relative positions and velocities are '
             'consistent.' % (frame.name, candidates, self.name,
                              candidates[0].name),
             UserWarning, stacklevel=2)
    neighbor = candidates[0]
    self.set_vel(frame, self.pos_from(neighbor).dt(frame) +
                 neighbor._vel_dict[frame])

